package com.lingo.app

data class VocabEntry(val term: String, val meaning: String, val example: String, val note: String)
data class DialogueLine(val speaker: String, val text: String, val translation: String)
data class ReadingText(val title: String, val body: String, val translation: String, val questions: List<Pair<String, String>>)
data class QuizItem(val prompt: String, val options: List<String>, val answer: Int, val explanation: String)
data class GrammarPoint(val title: String, val pattern: String, val explanation: String, val examples: List<Pair<String, String>>)
data class WritingTask(val title: String, val situation: String, val instruction: String, val starter: String, val sample: String, val translation: String)
data class LessonUnit(
    val title: String,
    val goal: String,
    val dialogue: List<DialogueLine>,
    val vocabulary: List<VocabEntry>,
    val reading: ReadingText,
    val quiz: List<QuizItem>
)
data class LanguageCourse(
    val id: String,
    val name: String,
    val nativeName: String,
    val flag: String,
    val description: String,
    val units: List<LessonUnit>
) {
    val firstUnit: LessonUnit get() = units.first()
}

