        "tr" to WritingTask("Yeni bir arkadaşına mesaj", "Ты пишешь новому знакомому и предлагаешь вместе изучить район.", "Напиши 4–6 предложений: поздоровайся, расскажи, что недавно приехал, предложи встретиться и спроси, когда удобно.", "Merhaba! Buraya ...", "Merhaba Deniz! Buraya geçen hafta taşındım ve mahalleyi henüz iyi tanımıyorum. Hafta sonu birlikte gezmek ister misin? Cumartesi öğleden sonra müsaitim. Sana uygun mu?", "Привет, Дениз! Я переехал сюда на прошлой неделе и пока плохо знаю район. Хочешь вместе погулять на выходных? В субботу после обеда я свободен. Тебе подходит?"),
        "ja" to WritingTask("友だちへのメッセージ", "Ты пишешь новому знакомому и предлагаешь вместе сходить в кафе.", "Напиши 3–5 коротких предложений: поздоровайся, предложи день и место, спроси, удобно ли это.", "こんにちは。土曜日に ...", "こんにちは、ゆきさん。土曜日にカフェへ行きませんか。午後二時はどうですか。駅の近くで会いましょう。時間がありますか。", "Здравствуйте, Юки. Не хотите сходить в кафе в субботу? Как насчёт двух часов дня? Давайте встретимся возле станции. У вас будет время?")
    )

    fun writing(id: String): WritingTask? = writingByLanguage[id]

    fun grammar(id: String): List<GrammarPoint> = grammarByLanguage[id].orEmpty()

    fun find(id: String): LanguageCourse = courses.firstOrNull { it.id == id } ?: courses.first()
}
